import React from 'react';
import { Line } from 'react-chartjs-2';

function RiskLineChart({ risks }) {
  // Group risks by month
  const countsByMonth = {};
  risks.forEach(r => {
    const date = new Date(r.date_reported);
    const month = `${date.getFullYear()}-${date.getMonth() + 1}`; // e.g. "2026-7"
    countsByMonth[month] = (countsByMonth[month] || 0) + 1;
  });

  const months = Object.keys(countsByMonth).sort();
  const counts = months.map(m => countsByMonth[m]);

  const data = {
    labels: months,
    datasets: [
      {
        label: 'Risks Reported',
        data: counts,
        fill: false,
        borderColor: '#f59e0b', // orange line
        tension: 0.1,
      },
    ],
  };

  return (
    <div style={{ width: '600px', marginTop: '20px' }}>
      <h2>Risks Reported Over Time</h2>
      <Line data={data} />
    </div>
  );
}

export default RiskLineChart;
